package com.meshcoreone.android.core.services.reactions

import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import org.junit.jupiter.api.Test

class ReactionHashIndependentVectorsTest {
    @Test
    fun deterministicHelloHasIndependentExpectedHash() {
        assertEquals(150804507u, MeshCoreOpenReactionParser.dartStringHash("hello"))
        assertEquals(150804507u, MeshCoreOpenReactionParser.dartStringHash("hello".map { it.code.toUShort() }))
    }

    @Test
    fun singleCharacterHasIndependentExpectedHash() {
        assertEquals(170824770u, MeshCoreOpenReactionParser.dartStringHash("a"))
    }

    @Test
    fun senderNameMatchesLiteralV1WireHash() {
        assertEquals(305741885u, MeshCoreOpenReactionParser.dartStringHash("TestNode"))
        val parsed = assertNotNull(MeshCoreOpenReactionParser.parseV1("r:1700000000000_305741885_12345:\ud83d\udc4d"))
        assertEquals(305741885u, parsed.senderNameHash)
    }

    @Test
    fun messageTextMatchesLiteralV1WireHash() {
        assertEquals(657738659u, MeshCoreOpenReactionParser.dartStringHash("Hello from mesh"))
        val parsed = assertNotNull(MeshCoreOpenReactionParser.parseV1("r:1700000000000_12345_657738659:\ud83d\udc4d"))
        assertEquals(657738659u, parsed.textHash)
    }

    @Test
    fun v1RoundTripMatchesIndependentLiteralFields() {
        assertEquals(690979482u, MeshCoreOpenReactionParser.dartStringHash("AVN1"))
        assertEquals(539648391u, MeshCoreOpenReactionParser.dartStringHash("Test message content"))
        val parsed = assertNotNull(MeshCoreOpenReactionParser.parseV1("r:1772600903000_690979482_539648391:\ud83d\udc4d"))
        assertEquals(1772600903u, parsed.timestampSeconds)
        assertEquals(690979482u, parsed.senderNameHash)
        assertEquals(539648391u, parsed.textHash)
        assertEquals("\ud83d\udc4d", parsed.emoji)
        assertEquals("1772600903_690979482_539648391", parsed.messageIdHash)
    }

    @Test
    fun fullChannelWireMatchesIndependentCrockfordVector() {
        assertEquals("3pe3nahw", ReactionParser.generateMessageHash("What's the situation at Main St today?", 1704067200u))
        assertEquals(
            "@[AlphaNode]\ud83d\udc4d\n3pe3nahw",
            ReactionService().buildReactionText("\ud83d\udc4d", "AlphaNode", "What's the situation at Main St today?", 1704067200u),
        )
    }

    @Test
    fun shortChannelAndDirectWireMatchIndependentCrockfordVector() {
        assertEquals("zgya0xt2", ReactionParser.generateMessageHash("ok", 1704067200u))
        assertEquals(
            "@[Node]\u2764\ufe0f\nzgya0xt2",
            ReactionService().buildReactionText("\u2764\ufe0f", "Node", "ok", 1704067200u),
        )
        assertEquals("\u2764\ufe0f\nzgya0xt2", ReactionService().buildDMReactionText("\u2764\ufe0f", "ok", 1704067200u))
    }

    @Test
    fun utf8AndUnsignedLittleEndianBoundariesMatchIndependentVectors() {
        val vectors = listOf(
            Triple("", 0u, "vwzp3604"),
            Triple("caf\u00e9", 1u, "zrgd9q90"),
            Triple("cafe\u0301", 1u, "vat3s086"),
            Triple("\ud83c\udf89abc", 2147483649u, "5ttb578g"),
            Triple("\u6f22\u5b57", 4294967295u, "tbz38qvw"),
        )
        vectors.forEach { (text, timestamp, expected) ->
            assertEquals(expected, ReactionParser.generateMessageHash(text, timestamp), "$text / $timestamp")
        }
    }
}
